/* @lc app=leetcode id=1000 lang=kotlin */

class Solution {
    fun mergeStones(stones: IntArray, k: Int): Int = IntArray(1).let { res -> if ((stones.size - 1) % (k - 1) != 0) res[0] = -1 else intArrayOf(stones.size, k, 0, 0, 0, 0, 0).let { v -> IntArray(stones.size + 1).let { pre -> Array(stones.size) { Array(stones.size) { IntArray(k + 1) } }.let { dp -> run { while (v[2] < v[0]) run { pre[v[2] + 1] = pre[v[2]] + stones[v[2]] }.also { v[3] = 0 }.also { while (v[3] < v[0]) run { v[4] = 1 }.also { while (v[4] <= k) run { dp[v[2]][v[3]][v[4]] = 9999999 }.also { v[4] += 1 } }.also { dp[v[2]][v[2]][1] = 0 }.also { v[3] += 1 } }.also { v[2] += 1 } }.also { v[2] = 2 }.also { while (v[2] <= v[0]) run { v[3] = 0 }.also { while (v[3] <= v[0] - v[2]) run { v[4] = v[3] + v[2] - 1 }.also { v[5] = 2 }.also { while (v[5] <= k) run { v[6] = v[3] }.also { while (v[6] < v[4]) run { dp[v[3]][v[4]][v[5]] = minOf(dp[v[3]][v[4]][v[5]], dp[v[3]][v[6]][1] + dp[v[6] + 1][v[4]][v[5] - 1]) }.also { v[6] += v[1] - 1 } }.also { v[5] += 1 } }.also { dp[v[3]][v[4]][1] = dp[v[3]][v[4]][k] + pre[v[4] + 1] - pre[v[3]] }.also { v[3] += 1 } }.also { v[2] += 1 } }.also { res[0] = dp[0][v[0] - 1][1] } } } } }.let { res[0] }
}